/**
 * @file font_ui.h
 * @brief Anti-aliased proportional UI fonts (Inter, SIL OFL 1.1), ASCII 32..126.
 *        Tables are generated by tools/gen_font.py into src/gfx/font_ui.c.
 */
#pragma once

#include <stdint.h>

#define FONT_FIRST 32
#define FONT_LAST  126

typedef struct {
    uint16_t off;       /* start of the w*h coverage bytes in the face bitmap */
    uint8_t  w, h;      /* bitmap size                                         */
    int8_t   xo, yo;    /* bitmap origin relative to pen / baseline (yo < 0 = above) */
    uint8_t  adv;       /* pen advance in pixels                               */
} font_glyph_t;

typedef struct {
    uint8_t             box_h;      /* line box height used by the layout        */
    uint8_t             baseline;   /* baseline distance from the top of the box */
    const font_glyph_t *glyph;      /* FONT_LAST - FONT_FIRST + 1 entries        */
    const uint8_t      *bitmap;
} font_t;

extern const font_t font_body;      /* 16 px, Inter Medium   */
extern const font_t font_title;     /* 30 px, Inter SemiBold */
